import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';

const AJV_OPTIONS = {strict: false, validateFormats: false} as const;

function validationPath(error: ErrorObject | undefined, missingProperty?: string): string {
  const rawPath =
    error && 'instancePath' in error
      ? String(error.instancePath)
      : error && 'dataPath' in error
        ? String(error.dataPath)
        : '';
  const path = rawPath.replace(/^[/.]/, '').replaceAll('/', '.');
  return missingProperty ? [path, missingProperty].filter(Boolean).join('.') : path || '(input)';
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validatorCompiler = new Ajv(AJV_OPTIONS);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validationResult(
    tool: StoredTool,
    definition: ToolDefinition,
    input: Record<string, unknown>
  ): ToolResponse | undefined {
    const validator = tool.validator ?? this.validatorFor(definition.inputSchema);
    if (validator(input)) return undefined;
    const error = validator.errors?.[0];
    const params = error?.params as {missingProperty?: string; type?: string} | undefined;
    const path = validationPath(error, params?.missingProperty);
    const detail =
      error?.keyword === 'required'
        ? 'required'
        : error?.keyword === 'enum'
          ? 'must satisfy enum constraint'
          : `must be ${params?.type ?? error?.keyword ?? 'valid'}`;
    log.warn('tool', 'input validation failed', {
      name: definition.name,
      failures: (validator.errors ?? []).map(error => ({
        path: validationPath(error, (error.params as {missingProperty?: string}).missingProperty),
        constraint: error.keyword,
      })),
    });
    return {result: `${path} ${detail}`};
  }

  private validatorFor(schema: Record<string, unknown>): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.validatorCompiler.compile(schema);
    this.validators.set(schema, validator);
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.validatorCompiler.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool schema, returning rejections and throwing only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validationResult = this.validationResult(tool, definition, input);
    if (validationResult) return validationResult;
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry input validation', () => {
  it('rejects missing required input before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(weatherDefinition(), async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required/i),
      executorCalls: 0,
    });
  });

  it('passes valid input and undeclared properties through unchanged exactly once', async () => {
    // specs/hal-engine-tool-input-validation#2
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const received: Array<Record<string, unknown>> = [];
    registry.register(weatherDefinition(), async toolInput => {
      received.push(toolInput);
      return 'sunny';
    });

    await registry.execute('weather', input);

    expect(received).toEqual([input]);
  });

  it('names the field and expected type when rejecting a wrong-typed property', async () => {
    const response = await executeWeather({location: 42});

    expect(response.result).toBe('location must be string');
  });

  it('names the enum constraint when rejecting a value outside the enum', async () => {
    // specs/hal-engine-tool-input-validation#4
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {unit: 'kelvin'});

    expect(response.result).toBe('unit must satisfy enum constraint');
  });

  it('reports nested property paths in validation rejections', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile',
        description: 'Read a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {name: {type: 'string'}}}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('profile', {profile: {name: 42}});

    expect(response.result).toBe('profile.name must be string');
  });

  it('reports the full nested property path when a required property is missing', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'profile',
        description: 'Read a profile',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', required: ['name']}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('profile', {profile: {}});

    expect(response.result).toBe('profile.name required');
  });

  it('formats a deeper missing required property path without duplicate separators', async () => {
    // specs/hal-engine-tool-input-validation#6
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'account',
        description: 'Read an account',
        inputSchema: {
          type: 'object',
          properties: {account: {type: 'object', properties: {profile: {type: 'object', required: ['name']}}}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('account', {account: {profile: {}}});

    expect(response.result).toBe('account.profile.name required');
  });

  it('does not prefix top-level validation paths with punctuation', async () => {
    const response = await executeWeather({location: 42});

    expect(response.result.startsWith('.')).toBe(false);
  });

  it('accepts union types when strict schema checking is disabled', async () => {
    // specs/hal-engine-tool-input-validation#10
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nullable_weather',
        description: 'Get weather with an optional location',
        inputSchema: {type: 'object', properties: {location: {type: ['string', 'null']}}},
      },
      async input => `weather for ${String(input.location)}`
    );

    const response = await registry.execute('nullable_weather', {location: null});

    expect(response.result).toBe('weather for null');
  });

  it('reuses a static schema validator across ten executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register({name: 'weather', description: 'Get weather', inputSchema: schema}, async () => 'sunny');
    const compileMock = compile.mock;
    const compileCountAfterRegister = compileMock.calls.length;

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {location: 'Berlin'})));

    expect({compileCountAfterRegister, compileCountAfterExecutions: compileMock.calls.length}).toEqual({
      compileCountAfterRegister: 1,
      compileCountAfterExecutions: 1,
    });
    compile.mockRestore();
  });

  it('validates each definition returned by a function-valued source', async () => {
    let useStringSchema = true;
    const received: Array<Record<string, unknown>> = [];
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic input',
        inputSchema: {
          type: 'object',
          properties: {value: {type: useStringSchema ? 'string' : 'number'}},
          required: ['value'],
        },
      }),
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    const firstResponse = await registry.execute('dynamic', {value: 'first'});
    useStringSchema = false;
    const secondResponse = await registry.execute('dynamic', {value: 2});

    expect({firstResponse, secondResponse, received}).toEqual({
      firstResponse: {result: 'ok'},
      secondResponse: {result: 'ok'},
      received: [{value: 'first'}, {value: 2}],
    });
  });
});

function weatherDefinition() {
  return {
    name: 'weather',
    description: 'Get weather',
    inputSchema: {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    },
  };
}

async function executeWeather(input: Record<string, unknown>) {
  const registry = new ToolRegistry();
  registry.register(weatherDefinition(), async () => 'sunny');
  return registry.execute('weather', input);
}
